rule Suspicious_PNG_LSBRaw {
    meta:
        description = "Detects PNG files with suspiciously high LSB entropy, indicative of potential steganographic content"
        author = "SOC Team"
        reference = "INC-2026-0718"
        date = "2026-04-09"
        hash = "abcdef1234567890abcdef1234567890abcdef1234567890abcdef1234567890"
    strings:
        $png_header = { 89 50 4E 47 0D 0A 1A 0A }
        $iend_chunk = { 49 45 4E 44 AE 42 60 82 }
        $lsb_pattern = /\x0[0-9A-F]{1}/ wide ascii
    condition:
        uint32be(0) == 0x89504E47 and
        for any i in (1..#lsb_pattern): (
            entropy(@lsb_pattern[i]..(@lsb_pattern[i] + 0x100)) > 7.0
        )
}

